# Spike 037: generate steamclient_probe.c + steamclient.def from exports.txt (the real Windows
# steamclient.dll's export names, via: objdump -p steamclient.dll | awk '/Ordinal +RVA +Name/{f=1;next} f&&NF>=3{print $NF}')
names = [l.strip() for l in open('exports.txt') if l.strip()]
c = ['/* Spike 037: logging stand-in for the Windows steamclient.dll that ActiveProcess\\\\SteamClientDll names.',
     ' * GENERATED by gen.py from the real DLL\'s export table (exports.txt). Every export logs its name (and',
     ' * CreateInterface its version string) to C:\\\\steamclient037.log and returns 0/NULL. All Steam client',
     ' * exports are __cdecl on i386, so a zero-arg stub is caller-cleaned and ABI-safe. */',
     '#include <windows.h>', '#include <stdio.h>',
     'static void lg(const char *fmt, const char *a) {',
     '  FILE *f = fopen("C:\\\\steamclient037.log", "a"); SYSTEMTIME st; if (!f) return; GetSystemTime(&st);',
     '  fprintf(f, "%02d:%02d:%02d.%03d pid=%lu tid=%lu ", st.wHour, st.wMinute, st.wSecond, st.wMilliseconds,',
     '          GetCurrentProcessId(), GetCurrentThreadId());',
     '  fprintf(f, fmt, a); fputc(\'\\n\', f); fclose(f);', '}',
     'BOOL WINAPI DllMain(HINSTANCE h, DWORD r, LPVOID p) { if (r == DLL_PROCESS_ATTACH) lg("DllMain attach %s", ""); return TRUE; }',
     '__declspec(dllexport) void *CreateInterface(const char *ver, int *rc) {',
     '  lg("CreateInterface(\\"%s\\") -> NULL", ver ? ver : "(null)"); if (rc) *rc = 1; return NULL; }']
for n in names:
    if n != 'CreateInterface':
        c.append('__declspec(dllexport) int %s(void) { lg("%%s() -> 0", "%s"); return 0; }' % (n, n))
open('steamclient_probe.c', 'w').write('\n'.join(c) + '\n')
open('steamclient.def', 'w').write('LIBRARY steamclient.dll\nEXPORTS\n' + ''.join('  %s\n' % n for n in names))
